/**
 * The structural shapes of the Prisma model delegates the stores call. Prisma
 * generates a different delegate type per model, so the stores accept anything
 * with these methods.
 */

export interface PrismaUserDelegate {
  findFirst(args: any): PromiseLike<any>;
  create(args: any): PromiseLike<any>;
  /**
   * Generated by Prisma for PostgreSQL, CockroachDB and SQLite. When present,
   * sign-up inserts with `skipDuplicates`, so a taken address is no failed
   * statement (see `PrismaUserStore.create`).
   */
  createManyAndReturn?(args: any): PromiseLike<any[]>;
  updateMany(args: any): PromiseLike<{ count: number }>;
}

export interface PrismaAuthTokenDelegate {
  upsert(args: any): PromiseLike<any>;
  findUnique(args: any): PromiseLike<any>;
  delete(args: any): PromiseLike<any>;
  update(args: any): PromiseLike<any>;
  deleteMany(args: any): PromiseLike<{ count: number }>;
}

/** The delegates of the two-factor tables in `prisma/auth.prisma`. */
export interface PrismaTwoFactorDelegates {
  /** `prisma.authTwoFactor` */
  readonly factor: {
    findUnique(args: any): PromiseLike<any>;
    create(args: any): PromiseLike<any>;
    updateMany(args: any): PromiseLike<{ count: number }>;
    deleteMany(args: any): PromiseLike<{ count: number }>;
  };
  /** `prisma.authRecoveryCodes` */
  readonly recoveryCodes: {
    findUnique(args: any): PromiseLike<any>;
    upsert(args: any): PromiseLike<any>;
    updateMany(args: any): PromiseLike<{ count: number }>;
    deleteMany(args: any): PromiseLike<{ count: number }>;
  };
  /** `prisma.authTrustedDevice` */
  readonly trustedDevice: {
    findUnique(args: any): PromiseLike<any>;
    findMany(args: any): PromiseLike<any[]>;
    create(args: any): PromiseLike<any>;
    deleteMany(args: any): PromiseLike<{ count: number }>;
  };
  /** `prisma.authStepUp` */
  readonly stepUp: {
    findUnique(args: any): PromiseLike<any>;
    upsert(args: any): PromiseLike<any>;
  };
}
